#!/usr/bin/env python3
"""What `sweep.py` claims about footers and `WORK/` notes, as tests rather than
as prose.

Run: python3 -m unittest discover -s .agents/skills/sweep -p 'test_*.py'
"""
import os
import pathlib
import tempfile
import unittest
import contextlib
import io
import urllib.error

import sweep


class Footer(unittest.TestCase):
    """Configured attribution marks agent replies, regardless of harness."""

    def setUp(self):
        self.setup = {
            "USER": "toumix",
            "AGENT_FOOTERS": ["example.test/agent", "Generated by Test Harness",
                              "Generated by Another Harness"],
        }

    def comment(self, body, user="toumix"):
        return {"body": body, "user": {"login": user}}

    def test_an_unconfigured_harness_does_not_answer(self):
        self.assertFalse(sweep.answered(
            self.comment("Done.\n\nGenerated by Unknown Harness"), self.setup))

    def test_a_bare_marker_on_the_last_line_answers(self):
        for marker in ("Generated by Test Harness", "Generated by Another Harness"):
            with self.subTest(marker=marker):
                self.assertTrue(sweep.answered(
                    self.comment(f"Done.\n\n{marker}"), self.setup))

    def test_a_link_label_never_answers_however_exactly_it_reads(self):
        """The label is the half a human types and the target is the half the
        runtime emits, so a matching label over any destination would let a
        comment silence its own thread."""
        self.assertFalse(sweep.answered(self.comment(
            "Done.\n\n[Generated by Test Harness](https://anywhere-at-all.example)"),
            self.setup))

    def test_a_runtime_wanting_a_linked_footer_lists_its_url_token(self):
        self.assertTrue(sweep.answered(self.comment(
            "Done.\n\n[Generated by Test Harness](https://share.example/session)"),
            {**self.setup, "AGENT_FOOTERS": [*self.setup["AGENT_FOOTERS"],
                                             "share.example"]}))

    def test_a_url_marker_inside_the_link_target_answers(self):
        """A configured URL token matches a linked footer inside emphasis."""
        self.assertTrue(sweep.answered(self.comment(
            "Done.\n\n_Generated by [Test Harness](https://example.test/agent)_"),
            self.setup))

    def test_a_session_id_in_the_target_still_answers(self):
        self.assertTrue(sweep.answered(self.comment(
            "Done.\n\n_Generated by [Test Harness]"
            "(https://example.test/agent/session_123)_"),
            self.setup))

    def test_a_marker_in_prose_does_not_answer(self):
        self.assertFalse(sweep.answered(self.comment(
            "This line mentions Generated by Test Harness in prose."), self.setup))

    def test_a_marker_must_be_on_the_final_line(self):
        self.assertFalse(sweep.answered(self.comment(
            "Generated by Test Harness\nA later human-authored line."), self.setup))

    def test_an_empty_marker_never_matches(self):
        self.assertFalse(sweep.agent_footer(
            "A human-authored line.", {"AGENT_FOOTERS": ["", "  "]}))

    def test_no_footers_configured_matches_nothing(self):
        self.assertFalse(sweep.agent_footer("Generated by Test Harness", {}))

    def test_anyone_but_USER_always_answers(self):
        self.assertTrue(sweep.answered(
            self.comment(None, user="toumix-agents"), self.setup))

    def test_a_body_USER_wrote_with_no_footer_is_unanswered(self):
        self.assertFalse(sweep.answered(
            self.comment("what did Evening do?"), self.setup))


class Stale(unittest.TestCase):
    """A note carries the date it was read, so staleness is arithmetic rather
    than discipline — the drift no amount of "remember to check" ever fixed."""

    def test_a_note_read_after_its_item_moved_is_current(self):
        self.assertEqual(sweep.stale({489: "2026-09-01"},
                                     {489: "2026-08-30T12:00:00Z"}), [])

    def test_same_day_is_current_whatever_the_hour(self):
        self.assertEqual(sweep.stale({489: "2026-09-01"},
                                     {489: "2026-09-01T23:59:59Z"}), [])

    def test_an_item_that_moved_a_day_later_is_stale(self):
        self.assertEqual(sweep.stale({489: "2026-08-31"},
                                     {489: "2026-09-01T00:00:01Z"}), [489])

    def test_a_note_with_no_readable_date_cannot_say_when_it_was_true(self):
        self.assertEqual(sweep.stale({489: None},
                                     {489: "2026-09-01T00:00:00Z"}), [489])

    def test_a_note_whose_item_is_not_open_is_not_stale_but_orphan(self):
        self.assertEqual(sweep.stale({676: "2020-01-01"}, {}), [])


class Cited(unittest.TestCase):
    """Forming a view on one item pulls in what it references: that is how an
    issue earns a note without a human deciding it has."""

    def test_numbers_are_read_out_of_prose(self):
        self.assertEqual(sweep.cited(["waits on #625, blocks #443"]),
                         {625, 443})

    def test_every_note_contributes(self):
        self.assertEqual(sweep.cited(["#1", "#2 and #1"]), {1, 2})

    def test_another_repos_number_is_not_the_notes_own(self):
        self.assertEqual(sweep.cited(
            ["builds on rel-int/optyx#16, see desire#162, v2#17, path.#18,",
             "repo-#20, other/bio#21 and (#54's ruling)"], "rel-int/bio"),
            {54})

    def test_the_notes_own_repo_and_a_list_are_its_own(self):
        self.assertEqual(sweep.cited(
            ["on discopy#803 and discopy/discopy#804, with #21/#23/#24"],
            "discopy/discopy"), {803, 804, 21, 23, 24})

    def test_a_note_citing_nothing_pulls_in_nothing(self):
        self.assertEqual(sweep.cited(["no numbers here"]), set())


class Notes(unittest.TestCase):
    """`notes` is the whole rule: one file per open item, deleted when the
    item is not open any more."""

    def test_agreement_is_silent(self):
        self.assertEqual(sweep.notes({489, 443}, {443, 489}), ([], []))

    def test_an_item_with_no_note_is_missing(self):
        self.assertEqual(sweep.notes({489}, {489, 443}), ([443], []))

    def test_a_note_with_no_open_item_is_an_orphan(self):
        self.assertEqual(sweep.notes({489, 676}, {489}), ([], [676]))

    def test_both_at_once_and_sorted(self):
        self.assertEqual(sweep.notes({9, 2}, {3, 1}), ([1, 3], [2, 9]))

    def test_nothing_open_makes_every_note_an_orphan(self):
        self.assertEqual(sweep.notes({1, 2}, set()), ([], [1, 2]))


class Required(unittest.TestCase):
    """A note is owed by our own pull requests and by what a note cites,
    never by an item merely being open."""

    setup = {"AGENT": "bot", "ADOPTED_PRS": {"a/b": [7]}}

    @staticmethod
    def pull(number, login):
        return {"number": number, "user": {"login": login},
                "pull_request": {}}

    def test_our_pull_request_is_required(self):
        items = [self.pull(1, "bot")]
        self.assertEqual(sweep.required("a/b", items, [], self.setup), {1})

    def test_someone_elses_pull_request_is_not(self):
        items = [self.pull(2, "alice")]
        self.assertEqual(sweep.required("a/b", items, [], self.setup), set())

    def test_an_adopted_pull_request_is_ours(self):
        items = [self.pull(7, "alice")]
        self.assertEqual(sweep.required("a/b", items, [], self.setup), {7})

    def test_a_cited_item_is_required_whoever_opened_it(self):
        items = [self.pull(2, "alice"), {"number": 3, "user": {"login": "x"}}]
        self.assertEqual(sweep.required(
            "a/b", items, ["collides with #2, waits on #3"], self.setup),
            {2, 3})

    def test_a_citation_of_a_closed_item_requires_nothing(self):
        self.assertEqual(sweep.required("a/b", [], ["#9"], self.setup), set())

    def test_our_issue_is_not_required_uncited(self):
        items = [{"number": 4, "user": {"login": "bot"}}]
        self.assertEqual(sweep.required("a/b", items, [], self.setup), set())


class MemoryClone(unittest.TestCase):
    """The memory clone is wherever the `config.env` we are configured by
    sits, so there is one answer rather than two that can disagree. A sweep
    against a memory repo carrying no `WORK/` still sweeps and says so, rather
    than reporting every open item as missing its note."""

    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()
        self.addCleanup(self.directory.cleanup)
        self.root = pathlib.Path(self.directory.name)

    def configured_by(self, path):
        os.environ["AGENTS_CONFIG"] = str(path)
        self.addCleanup(os.environ.pop, "AGENTS_CONFIG", None)

    def test_the_clone_is_the_config_file_s_own_directory(self):
        (self.root / "WORK").mkdir()
        (self.root / "config.env").write_text("MEMORY_REPO=someone/memory\n")
        self.configured_by(self.root / "config.env")
        self.assertEqual(sweep.memory_clone(), self.root)

    def test_a_clone_without_WORK_is_not_one_we_can_check(self):
        (self.root / "config.env").write_text("MEMORY_REPO=someone/memory\n")
        self.configured_by(self.root / "config.env")
        self.assertIsNone(sweep.memory_clone())

    def test_a_config_path_that_does_not_exist_is_none(self):
        self.configured_by(self.root / "nowhere" / "config.env")
        self.assertIsNone(sweep.memory_clone())


class Config(unittest.TestCase):
    """`config.env` is the one file naming USER, AGENT and the repos, so a
    malformed line raises rather than parsing to a key nobody reads."""

    def parse(self, text):
        directory = tempfile.TemporaryDirectory()
        self.addCleanup(directory.cleanup)
        path = pathlib.Path(directory.name) / "config.env"
        path.write_text(text)
        return sweep.config(path)

    def test_values_keep_everything_after_the_first_equals(self):
        self.assertEqual(self.parse("AGENT_EMAIL=a=b@c\n")["AGENT_EMAIL"],
                         "a=b@c")

    def test_work_repos_is_a_list(self):
        self.assertEqual(self.parse("WORK_REPOS=a/b,c/d\n")["WORK_REPOS"],
                         ["a/b", "c/d"])

    def test_footers_are_a_list_and_keep_their_spaces(self):
        self.assertEqual(
            self.parse("AGENT_FOOTERS=example.test/agent,Generated by Test Harness\n")
            ["AGENT_FOOTERS"], ["example.test/agent", "Generated by Test Harness"])

    def test_an_empty_footer_entry_is_dropped(self):
        self.assertEqual(self.parse("AGENT_FOOTERS=a,, ,b\n")["AGENT_FOOTERS"],
                         ["a", "b"])

    def test_adopted_prs_maps_repo_to_numbers(self):
        self.assertEqual(self.parse("ADOPTED_PRS=a/b:1,2 c/d:3\n")
                         ["ADOPTED_PRS"], {"a/b": [1, 2], "c/d": [3]})

    def test_an_empty_adopted_prs_is_no_repo(self):
        self.assertEqual(self.parse("ADOPTED_PRS=\n")["ADOPTED_PRS"], {})

    def test_comments_and_blank_lines_are_skipped(self):
        """The seed in `template/memory/config.env` ships commented, and the
        file is edited by hand, so a `#` line is not a malformed setting."""
        self.assertEqual(self.parse(
            "# what this file is\n\nUSER=toumix\n  # indented\nAGENT=agents\n"),
            {"USER": "toumix", "AGENT": "agents"})

    def test_a_hash_inside_a_value_is_kept(self):
        self.assertEqual(self.parse("APPROVE_EMOJI=rocket # not a comment\n")
                         ["APPROVE_EMOJI"], "rocket # not a comment")

    def test_a_line_with_no_key_raises(self):
        with self.assertRaises(ValueError):
            self.parse("USER=toumix\nnot a setting\n")


class ReviewComments(unittest.TestCase):
    """Whether an item has review comments is read off the item, not guessed
    from a status code: GitHub numbers issues and pulls in one space, and only
    a pull carries `pull_request`."""

    def setUp(self):
        self.asked = []
        original = sweep.get
        sweep.get = lambda repo, path: self.asked.append(path) or []
        self.addCleanup(setattr, sweep, "get", original)

    def test_an_issue_is_never_asked_about_on_the_pulls_endpoint(self):
        self.assertEqual(sweep.review_comments("a/b", 87, {}), [])
        self.assertEqual(self.asked, [])

    def test_a_pull_request_is(self):
        sweep.review_comments("a/b", 136, {"pull_request": {}})
        self.assertEqual(self.asked, ["pulls/136/comments"])

    def test_a_forbidden_listing_is_raised_not_read_as_an_issue(self):
        """A gateway answers 403 where GitHub answers 404, so a listing
        nobody read must never pass for one with no comments in it."""
        def forbidden(repo, path):
            raise urllib.error.HTTPError(path, 403, "Forbidden", {}, None)
        sweep.get = forbidden
        with self.assertRaises(urllib.error.HTTPError):
            sweep.review_comments("a/b", 136, {"pull_request": {}})


class Memory(unittest.TestCase):
    """One open day PR is the invariant, since the turn that opens a new day
    merges the previous one first. Two day PRs open, or two under one title,
    are findings; an `OTHERS/` PR beside the day's is none. The open day PR is
    named, to push today's turn to or merge before opening today's."""

    def patch(self, pulls):
        original = sweep.get
        sweep.get = lambda repo, path: pulls
        self.addCleanup(setattr, sweep, "get", original)

    def pull(self, title, ref, created_at):
        return {"title": title, "html_url": f"u/{ref}",
                "head": {"ref": ref}, "created_at": created_at}

    def run_memory(self):
        stderr = io.StringIO()
        with contextlib.redirect_stderr(stderr):
            findings = sweep.memory("a/memory")
        return findings, stderr.getvalue()

    def test_one_day_pr_beside_an_others_pr_is_no_finding(self):
        self.patch([self.pull("2026-09-07", "day", "2026-09-07T00:00:00Z"),
                    self.pull("OTHERS/x.md", "x", "2026-09-06T00:00:00Z")])
        findings, err = self.run_memory()
        self.assertEqual(findings, [])
        self.assertIn("'day'", err)
        self.assertNotIn("'x'", err)

    def test_two_day_prs_open_is_a_finding(self):
        self.patch([self.pull("2026-09-07", "b", "2026-09-07T00:00:00Z"),
                    self.pull("2026-09-04", "a", "2026-09-04T00:00:00Z")])
        findings, _ = self.run_memory()
        self.assertEqual(len(findings), 1)
        self.assertIn("2026-09-04, 2026-09-07", findings[0])

    def test_two_days_count_every_open_day_pr(self):
        self.patch([self.pull("2026-09-07", "c", "2026-09-07T00:00:00Z"),
                    self.pull("2026-09-07", "b", "2026-09-07T01:00:00Z"),
                    self.pull("2026-09-04", "a", "2026-09-04T00:00:00Z")])
        findings, _ = self.run_memory()
        self.assertEqual(len(findings), 2)
        self.assertTrue(any("3 day PRs open" in f for f in findings))

    def test_two_under_one_title_is_a_finding(self):
        self.patch([self.pull("2026-09-07", "b", "2026-09-07T00:00:00Z"),
                    self.pull("2026-09-07", "a", "2026-09-07T01:00:00Z")])
        findings, _ = self.run_memory()
        self.assertEqual(len(findings), 1)
        self.assertIn("2026-09-07", findings[0])

    def test_no_open_prs_names_no_day(self):
        self.patch([])
        findings, err = self.run_memory()
        self.assertEqual(findings, [])
        self.assertNotIn("day PR", err)


class Token(unittest.TestCase):
    """A runtime can sign `gh` in and export no variable: the readers then
    use `gh`'s token, and a variable still wins when one is set."""

    def setUp(self):
        from unittest import mock
        self.mock = mock
        sweep.gh_token.cache_clear()
        self.addCleanup(sweep.gh_token.cache_clear)

    def gh(self, **result):
        return self.mock.patch.object(sweep.subprocess, "run", **result)

    def test_a_variable_wins_and_gh_is_not_asked(self):
        with self.mock.patch.dict(os.environ, {"GH_TOKEN": "exported"}), \
                self.gh(side_effect=AssertionError("gh was asked")):
            self.assertEqual(sweep.token(), "exported")

    def test_with_no_variable_the_token_is_the_one_gh_holds(self):
        signed_in = self.mock.Mock(stdout="held\n")
        with self.mock.patch.dict(os.environ, clear=True), \
                self.gh(return_value=signed_in) as run:
            self.assertEqual(sweep.token(), "held")
            self.assertEqual(sweep.token(), "held")
        self.assertEqual(run.call_args.args[0], ["gh", "auth", "token"])
        self.assertEqual(run.call_count, 1)

    def test_no_gh_or_a_signed_out_one_is_no_token(self):
        import subprocess
        for error in (FileNotFoundError("gh"),
                      subprocess.CalledProcessError(1, "gh")):
            sweep.gh_token.cache_clear()
            with self.subTest(error=type(error).__name__), \
                    self.mock.patch.dict(os.environ, clear=True), \
                    self.gh(side_effect=error):
                self.assertEqual(sweep.token(), "")


class Fold(unittest.TestCase):
    """Inside the window an unanswered line prints; before it, the lines are
    one count carrying the newest of their dates, so a new one moves it."""

    waiting = [("2022-03-01T10:00:00Z", "#1 old"),
               ("2026-10-16T09:00:00Z", "#2 newest of the old"),
               ("2026-11-24T01:00:00Z", "#3 inside the window")]

    def test_lines_before_the_window_are_one_count_with_its_newest_date(self):
        self.assertEqual(
            sweep.fold("a/b", self.waiting, "2026-11-24T00:00:00Z"),
            ["#3 inside the window",
             "a/b: 2 older unanswered, newest 2026-10-16 — run with no"
             " --since to list them"])

    def test_a_line_written_at_the_window_s_start_is_inside_it(self):
        self.assertEqual(
            sweep.fold("a/b", self.waiting[2:], "2026-11-24T01:00:00Z"),
            ["#3 inside the window"])

    def test_with_no_window_every_line_prints(self):
        self.assertEqual(sweep.fold("a/b", self.waiting, ""),
                         ["#1 old", "#2 newest of the old",
                          "#3 inside the window"])

    def test_nothing_waiting_is_nothing(self):
        self.assertEqual(sweep.fold("a/b", [], "2026-11-24T00:00:00Z"), [])


class Swept(unittest.TestCase):
    """The whole sweep of a repo against a fake GitHub: an unanswered line
    carries its date, a whole-repo sweep counts the old ones, and a sweep of
    named items lists them."""

    setup = {"USER": "ada", "AGENT": "ada-agents", "APPROVE_EMOJI":
             "rocket", "MEMORY_REPO": "a/memory", "DESIRE_REPO": "a/rules",
             "WORK_REPOS": [], "AGENT_FOOTERS": []}

    def setUp(self):
        quiet = {"rocket": 0, "eyes": 0}
        issues = {
            7: {"number": 7, "user": {"login": "ada"}, "body": "why?",
                "created_at": "2026-10-16T09:00:00Z", "reactions": quiet,
                "html_url": "u/7"},
            8: {"number": 8, "user": {"login": "ada"}, "body": "and this?",
                "created_at": "2026-11-24T01:00:00Z", "reactions": quiet,
                "html_url": "u/8"}}

        def get(repo, path):
            if path == "issues?state=open":
                return list(issues.values())
            if path.endswith("/comments") or path.startswith("issues?state=closed"):
                return []
            return issues[int(path.split("/")[1])]
        original = sweep.get
        sweep.get = get
        self.addCleanup(setattr, sweep, "get", original)

    def test_a_whole_repo_sweep_counts_what_predates_the_window(self):
        self.assertEqual(
            sweep.sweep("a/b", [], "2026-11-24T00:00:00Z", self.setup),
            ["#8 unanswered ada issue of 2026-11-24: u/8",
             "a/b: 1 older unanswered, newest 2026-10-16 — run with no"
             " --since to list them"])

    def test_a_sweep_of_named_items_lists_them_whatever_the_window(self):
        self.assertEqual(
            sweep.sweep("a/b", [7], "2026-11-24T00:00:00Z", self.setup),
            ["#7 unanswered ada issue of 2026-10-16: u/7"])


class Unsigned(unittest.TestCase):
    """GitHub alone says whether a commit is verified, so the sweep reads it
    for AGENT's commits on the open pull requests."""

    setup = {"AGENT": "ada-agents"}

    def commit(self, sha, verified, login="ada-agents", name="ada-agents"):
        return {"sha": sha, "html_url": f"u/{sha}",
                "author": login and {"login": login},
                "commit": {"author": {"name": name}, "verification": {
                    "verified": verified,
                    "reason": "valid" if verified else "unsigned"}}}

    def patch(self, commits):
        original = sweep.get
        sweep.get = lambda repo, path: (
            [{"number": 5}] if path == "pulls?state=open" else commits)
        self.addCleanup(setattr, sweep, "get", original)

    def test_an_unverified_commit_of_AGENT_s_is_a_finding(self):
        self.patch([self.commit("a" * 40, True), self.commit("b" * 40, False)])
        self.assertEqual(sweep.unsigned("a/memory", self.setup), [
            "a/memory#5: commit bbbbbbb of ada-agents's reads unsigned on"
            " GitHub, not verified: u/" + "b" * 40])

    def test_a_commit_GitHub_links_to_no_account_is_AGENT_s_by_its_name(self):
        self.patch([self.commit("c" * 40, False, login=None)])
        self.assertEqual(len(sweep.unsigned("a/memory", self.setup)), 1)

    def test_someone_else_s_unverified_commit_is_not_ours_to_report(self):
        self.patch([self.commit("d" * 40, False, login="ada", name="ada")])
        self.assertEqual(sweep.unsigned("a/memory", self.setup), [])


class OnDayBranch(unittest.TestCase):
    """`WORK/` is read from the checkout, and the day's notes are on the open
    day PR's branch: from any other branch the notes check would be about
    yesterday, so the sweep stops and names the branch."""

    setup = {"MEMORY_REPO": "a/memory"}

    def patch(self, pulls, branch):
        from unittest import mock
        for name, value in (("get", lambda repo, path: pulls),
                            ("checked_out", lambda root: branch)):
            patcher = mock.patch.object(sweep, name, value)
            patcher.start()
            self.addCleanup(patcher.stop)

    def day(self, ref="day-2026-09-07"):
        return {"title": "2026-09-07", "head": {"ref": ref}}

    def test_main_with_a_day_PR_open_is_refused_naming_its_branch(self):
        self.patch([self.day()], "main")
        with self.assertRaisesRegex(sweep.WrongBranch,
                                    "check out day-2026-09-07 first"):
            sweep.on_day_branch(pathlib.Path("clone"), self.setup)

    def test_a_detached_HEAD_is_refused_too(self):
        self.patch([self.day()], "")
        with self.assertRaises(sweep.WrongBranch):
            sweep.on_day_branch(pathlib.Path("clone"), self.setup)

    def test_the_day_PR_s_own_branch_passes(self):
        self.patch([self.day()], "day-2026-09-07")
        sweep.on_day_branch(pathlib.Path("clone"), self.setup)

    def test_with_no_day_PR_open_any_branch_passes(self):
        self.patch([{"title": "OTHERS/x.md", "head": {"ref": "x"}}], "main")
        sweep.on_day_branch(pathlib.Path("clone"), self.setup)

    def test_a_directory_that_is_no_checkout_has_no_branch_to_be_wrong(self):
        self.patch([self.day()], None)
        sweep.on_day_branch(pathlib.Path("clone"), self.setup)

    def test_the_branch_is_read_from_git(self):
        import subprocess
        with tempfile.TemporaryDirectory() as directory:
            root = pathlib.Path(directory)
            self.assertIsNone(sweep.checked_out(root))
            subprocess.run(["git", "init", "-q", "-b", "day-2026-09-07",
                            directory], check=True)
            self.assertEqual(sweep.checked_out(root), "day-2026-09-07")


class Incomplete(unittest.TestCase):
    """A dropped connection is an incomplete sweep, exit 2, never findings."""

    def test_the_wrong_branch_exits_2_and_says_which_to_check_out(self):
        from unittest import mock
        stderr = io.StringIO()
        with mock.patch.object(sweep, "sweep", side_effect=sweep.WrongBranch(
                    "check out day-2026-09-07 first")), \
                mock.patch.object(sweep, "find_config", return_value=None), \
                mock.patch.object(sweep, "config", return_value={}), \
                contextlib.redirect_stderr(stderr):
            self.assertEqual(sweep.main(["owner/repo"]), 2)
        self.assertIn("owner/repo: check out day-2026-09-07 first",
                      stderr.getvalue())

    def test_a_dropped_connection_exits_2(self):
        import http.client
        from unittest import mock
        for error in (http.client.RemoteDisconnected("closed"),
                      ConnectionResetError("reset"),
                      urllib.error.URLError("denied")):
            with self.subTest(error=type(error).__name__), \
                    mock.patch.object(sweep, "sweep", side_effect=error), \
                    mock.patch.object(sweep, "find_config", return_value=None), \
                    mock.patch.object(sweep, "config", return_value={}), \
                    contextlib.redirect_stderr(io.StringIO()):
                self.assertEqual(sweep.main(["owner/repo"]), 2)


if __name__ == "__main__":
    unittest.main()
